/bin/bash -lc 'set -eu
audit_dir=$(mktemp -d "$PWD/.contract-check.XXXXXX")
trap '"'python3 -c \"import shutil,sys; shutil.rmtree(sys.argv[1])\" \""'$audit_dir"'"' EXIT
cp -R release \""'$audit_dir/release"
cp vendor/hono-4.13.19.tgz "$audit_dir/"
cd "$audit_dir/release"
export npm_config_cache="$audit_dir/npm-cache"
npm install --offline --ignore-scripts --no-audit --no-fund ../hono-4.13.19.tgz
npm ls hono --depth=0
npm test
node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
import app from './app.mjs';

const cases = [
  ['a7', 'day', 200, {id: 'a7', title: 'Harbor'}, 'dispatch,session,read'],
  ['a7', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
  ['b4', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
  ['missing-card', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
  ['missing-card', 'day', 404, {error: 'not_found'}, 'dispatch,session,read'],
  ['b4', 'day', 502, {error: 'invalid_record'}, 'dispatch,session,read,error'],
];
for (const [id, shift, status, body, steps] of cases) {
  const request = new Request('http://localhost/desk/' + id, {
    headers: shift === undefined ? {} : {'x-shift': shift},
  });
  const response = await app.request(request);
  assert.ok(response instanceof Response);
  const actual = {
    status: response.status,
    body: await response.json(),
    steps: response.headers.get('x-desk-steps'),
  };
  console.log(JSON.stringify({id, shift: shift ?? null, ...actual}));
  try {
    assert.match(response.headers.get('content-type') ?? '', /"'^application'"\\/json(?:\\s*;|"'$)/i);
    assert.deepEqual(actual, {status, body, steps});
  } catch (error) {
    process.exitCode = 1;
    console.error(error.message);
  }
}
NODE'

